package io.github.campione01.mineclientbridge;
import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
import net.minecraft.client.Minecraft;
import net.minecraft.world.entity.MoverType;
import static io.github.campione01.mineclientbridge.LocalSegmentEngineChecks.*;
import static io.github.campione01.mineclientbridge.RouteStopEngineChecks.environment;
import static io.github.campione01.mineclientbridge.RouteStopEngineChecks.admit;
/** Unchanged production terrain/controller/dispatch over explicit immutable synthetic state readers. */
public final class TerrainEquivalenceEngineChecks {
 static int assertions;static JsonArray cases=new JsonArray();
 static void ok(boolean b,String why){assertions++;if(!b)throw new AssertionError(why);}
 static void scenario(String name,Runnable r){r.run();cases.add(name);System.out.println("PASS "+name);}
 static ClientActionRequest.Rejected refused(Runnable r){assertions++;try{r.run();}catch(ClientActionRequest.Rejected e){return e;}throw new AssertionError("Expected refusal");}
 static Minecraft leaves(String id){var mc=environment();mc.level.contextWall=true;mc.level.contextId=id;mc.level.contextState="[distance=3,persistent=false,waterlogged=false]";return mc;}
 static F start(){return admit(leaves("minecraft:oak_leaves"));}
 static Minecraft soil(String id){var mc=environment();mc.level.contextWall=true;mc.level.contextId=id;mc.level.contextState=id.equals("minecraft:grass_block")?"[snowy=false]":"";return mc;}
 static void settledSuccess(F f){sample(f,1,.8,1,true,-.0784,0);sample(f,2,1.1,1,true,-.0784,0);sample(f,3,1.4,1,true,-.0784,0);sample(f,4,1.47,1,true,-.0784,0);ok(!f.m().step().done(),"first settled sample");sample(f,5,1.47,1,true,-.0784,0);ok(f.m().step().done(),"actual controller completes second settled sample");f.m().markAttempted();ClientActions.finish("succeeded","path_reached");}
 static ClientActionRequest replacementRequest(){var r=request(0);var body=r.original().deepCopy();body.addProperty("action_id","replacement");return new ClientActionRequest("replacement",r.action(),r.timeoutMs(),r.waypoints(),null,null,null,-1,false,false,-1,-1,0,null,body);}
 static JsonObject proof(F f,ClientActionRequest.Rejected r,String phase,String code){
  var d=r.routeTerrainRejection;ok(d!=null,"actual terrain evidence retained");ok(d.equals(f.entry().result.get("route_terrain_rejection")),"owned result matches failure proof");
  ok(d.keySet().equals(Set.of("schema_version","profile","policy","phase","rejection_code","cell","original","current","changed_fields")),"closed diagnostic shape");
  ok(d.get("phase").getAsString().equals(phase)&&d.get("rejection_code").getAsString().equals(code),"actual phase/code "+d);
  var original=d.getAsJsonObject("original");boolean found=false;for(var row:f.m().facts().getAsJsonArray("cells"))if(row.equals(original))found=true;ok(found,"literal original witness cell");
  ok(d.getAsJsonObject("current").keySet().equals(Set.of("loaded","id","state","role","fluid_empty","full_cube","collision_empty","friction")),"all nullable current facts present");
  ok(!f.entry().result.has("route_threat_stop"),"no defense authority");return d;
 }
 public static void main(String[] args)throws Exception {Path out=Path.of(args[0]);
  scenario("default-only-audited-leaf-distance-persistent-current-capture",()->{for(String id:List.of("minecraft:oak_leaves","minecraft:birch_leaves")){var f=admit(leaves(id));String original=f.m().facts().toString();for(String s:List.of("[distance=4,persistent=false,waterlogged=false]","[distance=7,persistent=true,waterlogged=false]","[distance=2,persistent=false,waterlogged=false]")){f.mc().level.contextState=s;f.m().beforeEffect(f.mc());ok(!f.entry().result.has("route_terrain_rejection"),"accepted equivalents do not fabricate rejection");}ok(f.m().facts().toString().equals(original),"source witness immutable across callbacks");}});
  scenario("admission-recheck-and-final-admission-fence-stay-exact",()->{for(int k=0;k<2;k++){var mc=leaves("minecraft:oak_leaves");var r=request(0);var m=new ScopedLocalSegmentMovement(mc,r,System.nanoTime(),mc.level.time,false,true);String original=m.facts().toString();mc.level.contextState="[distance=4,persistent=false,waterlogged=false]";var failure=refused(()->{if(kHolder[0]==0)m.admissionRecheck(mc);else m.admissionRawFence(mc);});ok(failure.routeTerrainRejection==null&&ClientActions.active==null&&m.facts().toString().equals(original),"no admission relaxation or continuation proof");kHolder[0]++;}kHolder[0]=0;});
  scenario("old-legacy-and-explicit-defense-remain-state-strict",()->{for(int mode=0;mode<2;mode++){var mc=leaves("minecraft:oak_leaves");var r=mode==0?request(0):SpatialThreatEngineChecks.request();var m=new ScopedLocalSegmentMovement(mc,r,System.nanoTime(),mc.level.time,mode==1);var e=ClientActions.install(r,m);m.activate(e);mc.level.contextState="[distance=4,persistent=false,waterlogged=false]";ok(refused(()->m.beforeEffect(mc)).routeTerrainRejection==null&&!e.result.has("route_terrain_rejection"),"legacy no broadening");}});
  scenario("waterlogging-unknown-property-id-class-and-decay-refuse",()->{for(int mode=0;mode<6;mode++){var f=start();switch(mode){case 0->f.mc().level.contextFluid=true;case 1->f.mc().level.contextState="[distance=4,persistent=false,waterlogged=true]";case 2->f.mc().level.contextState="[distance=4,persistent=false,waterlogged=false,unknown=true]";case 3->f.mc().level.contextId="minecraft:birch_leaves";case 4->f.mc().level.contextBlockKind="plain";case 5->{f.mc().level.contextId="";f.mc().level.contextWall=false;}}var r=refused(()->f.m().beforeEffect(f.mc()));ok(r.routeTerrainRejection!=null,"unsafe change actual proof "+mode);ok(!f.entry().result.has("route_threat_stop"),"no defense or fallback");}});
  scenario("current-physics-revalidated-before-property-equivalence",()->{for(int mode=0;mode<4;mode++){var f=start();f.mc().level.contextState="[distance=4,persistent=true,waterlogged=false]";switch(mode){case 0->f.mc().level.contextSolid=false;case 1->f.mc().level.contextFriction=.7f;case 2->f.mc().level.contextFriction=Float.NaN;case 3->f.mc().level.contextFluid=true;}var r=refused(()->f.m().beforeEffect(f.mc()));var d=proof(f,r,"capture",mode==0?"local_segment_floor_unsupported":mode==3?"local_segment_fluid_present":"local_segment_special_friction");if(mode==2)ok(d.getAsJsonObject("current").get("friction").isJsonNull(),"nonfinite friction never serialized as number");}});
  scenario("grass-furnace-barrel-unreviewed-properties-stay-strict",()->{for(String id:List.of("minecraft:grass_block","minecraft:furnace","minecraft:barrel")){var mc=environment();mc.level.contextWall=true;mc.level.contextId=id;var f=admit(mc);mc.level.contextState=id.equals("minecraft:grass_block")?"[snowy=true]":id.equals("minecraft:furnace")?"[lit=true,facing=east]":"[open=true,facing=up]";proof(f,refused(()->f.m().beforeEffect(mc)),"equivalence","local_segment_footprint_changed");}});
  scenario("exact-context-grass-dirt-both-directions-current-capture",()->{for(String id:List.of("minecraft:grass_block","minecraft:dirt")){var mc=soil(id);var f=admit(mc);String original=f.m().facts().toString();mc.level.contextId=id.equals("minecraft:dirt")?"minecraft:grass_block":"minecraft:dirt";mc.level.contextState=mc.level.contextId.equals("minecraft:grass_block")?"[snowy=false]":"";f.m().beforeEffect(mc);ok(f.m().facts().toString().equals(original)&&!f.entry().result.has("route_terrain_rejection"),"context soil equivalent keeps original source");}});
  scenario("context-soil-unsupported-ids-snow-properties-and-class-refused",()->{for(String id:List.of("minecraft:mud","minecraft:dirt_path","minecraft:farmland","minecraft:snow","minecraft:powder_snow","minecraft:magma_block","minecraft:lava","minecraft:soul_sand","minecraft:coarse_dirt")){var mc=soil("minecraft:grass_block");var f=admit(mc);mc.level.contextId=id;mc.level.contextState="";var r=refused(()->f.m().beforeEffect(mc));ok(r.routeTerrainRejection!=null,"unsafe soil replacement refused "+id);}for(int mode=0;mode<4;mode++){var mc=soil("minecraft:dirt");var f=admit(mc);mc.level.contextId="minecraft:grass_block";mc.level.contextState=mode==0?"[snowy=true]":mode==1?"[snowy=false,unknown=true]":"[snowy=false]";if(mode==2)mc.level.contextBlockKind="plain";if(mode==3)mc.level.contextFluid=true;refused(()->f.m().beforeEffect(mc));}});
  scenario("support-and-clearance-never-borrow-context-soil-equivalence",()->{var mc=environment();mc.level.floorId="minecraft:grass_block";var f=admit(mc);mc.level.floorId="minecraft:dirt";var d=proof(f,refused(()->f.m().beforeEffect(mc)),"equivalence","local_segment_footprint_changed");ok(d.getAsJsonObject("original").get("role").getAsString().equals("support"),"same support stays exact");var clear=environment();var g=admit(clear);clear.level.airId="minecraft:grass_block";refused(()->g.m().beforeEffect(clear));});
  scenario("same-callback-grass-death-keeps-strict-raw-identity",()->{var mc=soil("minecraft:grass_block");var f=admit(mc);Hooks.once("friction",5,()->{mc.level.contextId="minecraft:dirt";mc.level.contextState="";});proof(f,refused(()->f.m().beforeEffect(mc)),"raw_fence","local_segment_corridor_changed_after_hooks");});
  scenario("context-soil-current-fullcube-and-friction-revalidated",()->{for(int mode=0;mode<2;mode++){var mc=soil("minecraft:grass_block");var f=admit(mc);mc.level.contextId="minecraft:dirt";mc.level.contextState="";if(mode==0)mc.level.contextSolid=false;else mc.level.contextFriction=.7f;proof(f,refused(()->f.m().beforeEffect(mc)),"capture",mode==0?"local_segment_floor_unsupported":"local_segment_special_friction");}});
  scenario("same-callback-safe-leaf-change-is-still-raw-refusal",()->{var f=start();Hooks.once("friction",5,()->f.mc().level.contextState="[distance=4,persistent=false,waterlogged=false]");var d=proof(f,refused(()->f.m().beforeEffect(f.mc())),"raw_fence","local_segment_corridor_changed_after_hooks");ok(d.getAsJsonObject("current").get("full_cube").isJsonNull()&&d.getAsJsonObject("current").get("friction").isJsonNull(),"raw fence never invokes shape/friction diagnostics");});
  scenario("same-text-new-state-identity-cannot-pass-raw-fence",()->{var f=start();Hooks.once("friction",0,()->f.mc().level.stateVersion++);var d=proof(f,refused(()->f.m().beforeEffect(f.mc())),"raw_fence","local_segment_corridor_changed_after_hooks");ok(d.getAsJsonArray("changed_fields").isEmpty(),"identity change not falsely claimed as changed field");});
  scenario("unloaded-capture-retains-unavailable-facts-honestly",()->{var f=start();f.mc().level.loaded=false;var d=proof(f,refused(()->f.m().beforeEffect(f.mc())),"capture","local_segment_unknown_corridor_cell");ok(d.getAsJsonObject("current").get("state").isJsonNull()&&d.getAsJsonArray("changed_fields").toString().equals("[\"loaded\"]"),"unread state is null");});
  scenario("bounded-proof-no-truncation-or-arbitrary-exception-text",()->{var f=start();f.mc().level.contextState="[unknown="+"x".repeat(513)+"]";var r=refused(()->f.m().beforeEffect(f.mc()));ok(r.routeTerrainRejection==null&&!f.entry().result.has("route_terrain_rejection"),"oversize evidence omitted without fabricating truncation");});
  scenario("reentrant-cancel-success-replacement-no-late-proof-write",()->{for(int mode=0;mode<5;mode++){var f=start();int chosen=mode;var replacement=new ClientActions.RuntimeAction(new ActionRegistry.Entry(request(0)),null);String[] original={null},other={replacement.entry.result.toString()};Hooks.once("friction",0,()->{if(chosen<2)ClientActions.finish(chosen==0?"cancelled":"succeeded",chosen==0?"cancel_requested":"path_reached");else if(chosen<4)ClientActions.active=replacement;else ClientActions.ownershipRevision++;original[0]=f.entry().result.toString();f.mc().level.contextFluid=true;});var r=refused(()->f.m().beforeEffect(f.mc()));ok(r.routeTerrainRejection!=null,"late exception retains actual proof");ok(f.entry().result.toString().equals(original[0])&&replacement.entry.result.toString().equals(other[0]),"old/replacement receipt unchanged "+mode);}});
  scenario("actual-full-posttick-catch-preserves-terminal-and-replacement-owners",()->{for(int mode=0;mode<4;mode++){var f=start();var entered=ClientActions.active;int chosen=mode;String[] original={null},replacement={null};ClientActions.RuntimeAction[] next={null};Hooks.once("friction",0,()->{ClientActions.finish(chosen==1?"succeeded":"cancelled",chosen==1?"path_reached":"cancel_requested");original[0]=f.entry().result.toString();if(chosen>=2){ClientActions.install(replacementRequest(),null);next[0]=ClientActions.active;replacement[0]=next[0].entry.result.toString();}f.mc().level.contextFluid=true;});var r=refused(()->f.m().beforeEffect(f.mc()));ClientActions.postTickFailure(entered,r);ok(f.entry().result.toString().equals(original[0]),"old terminal bytes unchanged");if(chosen>=2)ok(ClientActions.active==next[0]&&next[0].entry.running()&&next[0].entry.result.toString().equals(replacement[0]),"actual extracted catch leaves new owner running/untouched");else ok(ClientActions.active==null,"terminal owner remains absent");}});
  scenario("terrain-diagnostic-never-overrides-release-failure",()->{var f=start();f.mc().level.contextFluid=true;var r=refused(()->f.m().beforeEffect(f.mc()));ClientActions.released=false;ClientActions.finish("cancelled",r.getMessage());ok(f.entry().reason.equals("input_release_unconfirmed")&&f.entry().status.equals("failed")&&f.entry().result.get("requested_terminal_reason").getAsString().equals(r.getMessage())&&f.entry().result.has("route_terrain_rejection"),"release uncertainty remains authoritative");});
  scenario("late-motion-terrain-proof-stays-unknown",()->{var f=start();f.m().markAttempted();f.mc().level.contextFluid=true;ScopedLocalSegmentDispatch.arm(f.m());ok(!ScopedLocalSegmentDispatch.beforeMove(f.mc().player,MoverType.SELF,f.mc().player.velocity),"late move refused");ok(f.entry().result.has("route_terrain_rejection")&&f.entry().result.get("unknown_outcome").getAsBoolean()&&f.entry().result.get("effect_outcome").getAsString().equals("unknown"),"motion unknown preserved");});
  scenario("post-tick-terrain-proof-keeps-generic-failure-semantics",()->{var f=start();var entered=ClientActions.active;f.mc().level.contextFluid=true;var r=refused(()->f.m().beforeEffect(f.mc()));ClientActions.postTickFailure(entered,r);ok(f.entry().status.equals("failed")&&f.entry().reason.equals("client_action_error")&&f.entry().result.has("route_terrain_rejection"),"no promotion of post-tick failure");});
  scenario("current-leaf-equivalent-motion-gate-accepts-ordinary-move",()->{var f=start();f.mc().level.contextState="[distance=4,persistent=true,waterlogged=false]";ScopedLocalSegmentDispatch.arm(f.m());ok(ScopedLocalSegmentDispatch.beforeMove(f.mc().player,MoverType.SELF,f.mc().player.velocity),"ordinary exact requested move allowed after current raw fence");});
  var success=start();success.mc().level.contextState="[distance=4,persistent=true,waterlogged=false]";settledSuccess(success);writeFixture(out.resolve("terrain-equivalence-success"),success);
  var grass=admit(soil("minecraft:grass_block"));grass.mc().level.contextId="minecraft:dirt";grass.mc().level.contextState="";settledSuccess(grass);writeFixture(out.resolve("terrain-equivalence-grass-success"),grass);
  var failed=start();failed.m().beforeEffect(failed.mc());failed.m().markAttempted();failed.mc().level.contextFluid=true;var reason=refused(()->failed.m().beforeEffect(failed.mc()));ClientActions.finish("cancelled",reason.getMessage());writeFixture(out.resolve("terrain-equivalence-rejection"),failed);
  var motion=start();motion.m().markAttempted();motion.mc().level.contextFluid=true;ScopedLocalSegmentDispatch.arm(motion.m());ScopedLocalSegmentDispatch.beforeMove(motion.mc().player,MoverType.SELF,motion.mc().player.velocity);writeFixture(out.resolve("terrain-equivalence-motion"),motion);
  var post=start();var entered=ClientActions.active;post.mc().level.contextFluid=true;var rejected=refused(()->post.m().beforeEffect(post.mc()));ClientActions.postTickFailure(entered,rejected);writeFixture(out.resolve("terrain-equivalence-post-tick"),post);
  JsonObject report=new JsonObject();report.addProperty("assertions",assertions);report.add("cases",cases);report.addProperty("scope","Production controller, current terrain validation and real motion dispatch; immutable synthetic engine readers, no game or actual physics acceptance");Files.writeString(out.resolve("terrain-equivalence-result.json"),report.toString(),StandardOpenOption.CREATE_NEW);System.out.println("PASS assertions="+assertions);
 }
 static int[] kHolder={0};
}
